  "scenario_id": "sc-14cdd9",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "Death",
      "years": [2016, 2016],
      "pattern": "shock",
      "direction": "increase",
      "magnitude": "AE 1.163 in 2016 versus a ~0.97-1.02 range in 2017-2024; about +0.16 A/E or +47 claims over Expected=290. Death empirical A/E SD is ~0.060 versus an average Poisson sigma of ~0.047, so the row-specific Poisson z (~2.8) is indicative rather than decisive.",
      "confidence": 0.6,
      "evidence": [
        "artifacts/ae_death_by_year.csv 2016: Actual=337, Expected=290, AE=1.163",
        "artifacts/ae_death_by_year.csv 2017-2024: AE remains near 1.0 (0.966-1.019), so the 2016 move is not sustained",
        "summary.json: Death overall_ae=1.004, indicating the excursion is year-specific rather than a decade-level bias"
      ],
      "recommended_action": "Investigate 2016 death claims for reporting lag, data/coding changes, large or aggregated claims, and whether the 2016 mortality expectation is understated. If not explained by data quality or a one-off event, document as a mild experience shock in the experience study and monitor subsequent years; pricing/valuation follow-up only if corroborated."
    }
  ]
}

